cd /bench/repo; python3 - <<'EOF'
import os,re,subprocess,collections
decls=[]  # (name, isMethod, isExported, pkgdir, file)
for root,dirs,files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go'): continue
        p=os.path.join(root,f)
        for i,line in enumerate(open(p,encoding='utf8',errors='ignore'),1):
            m=re.match(r'^func\s+(\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*\(',line)
            if not m: continue
            n=m.group('name')
            if n.startswith(('Test','Benchmark','Example','Fuzz')) or n=='init': continue
            decls.append((n, bool(m.group('recv')), n[0].isupper(), root, p, i))
# gather all go files
allfiles=[]
for root,dirs,files in os.walk('.'):
    if '/.git' in root: continue
    for f in files:
        if f.endswith('.go'): allfiles.append(os.path.join(root,f))
content={p:open(p,encoding='utf8',errors='ignore').read().split('\n') for p in allfiles}
pkgname={}
for p in allfiles:
    for l in content[p][:30]:
        if l.startswith('package '): pkgname[p]=l.split()[1]; break

results=[]
for (n,ismeth,exp,pkgdir,decfile,decline) in decls:
    sites=[]
    for p in allfiles:
        samepkg = os.path.dirname(p)==pkgdir
        for i,l in enumerate(content[p],1):
            if l.lstrip().startswith('func ') and re.search(r'\b'+n+r'\s*\(',l) and p==decfile: continue
            if ismeth:
                if re.search(r'\.'+n+r'\(',l): sites.append((p,i))
            else:
                if samepkg and re.search(r'(?<![\w.])'+n+r'\(',l): sites.append((p,i))
                elif not samepkg and exp and re.search(r'\b'+os.path.basename(pkgdir)+r'\.'+n+r'\(',l): sites.append((p,i))
    nontest=[s for s in sites if not s[0].endswith('_test.go')]
    results.append((len(sites),len(nontest),n,decfile,decline,ismeth))
results.sort(reverse=True)
for r in results[:25]: print(r[0],r[1],r[2],r[3]+':'+str(r[4]),'method' if r[5] else 'func')
print('--- by nontest')
results.sort(key=lambda r:-r[1])
for r in results[:25]: print(r[0],r[1],r[2],r[3]+':'+str(r[4]),'method' if r[5] else 'func')
EOF
